(6986476, 1054099, 82999, '<td valign="top">This is a step away from being a really good image.  Love the idea, but soooo wish you couldn''t see the camera.  Suppose you could have hid it under an arm, or peaking out of someone''s shirt and remote triggered it.  And a bit more contrast around the perimeter I think would have helped.  <br/> <br/>That said, it''s one of the more creative images posted and I really like it.</td>', 'This is a step away from being a really good image.  Love the idea, but soooo wish you couldn''t see the camera.  Suppose you could have hid it under an arm, or peaking out of someone''s shirt and remote triggered it.  And a bit more contrast around the perimeter I think would have helped.   That said, it''s one of the more creative images posted and I really like it.', '2013-02-26 10:02:45.000000', NULL, 1),
(6986477, 1054145, 82999, '<td valign="top">Ha!.  That''s a heck of way to shoe horn any image into a challenge.  You get points just for that.<br/> <br/>I love how you used your facial expression to make the O too.  Very good.</td>', 'Ha!.  That''s a heck of way to shoe horn any image into a challenge.  You get points just for that. I love how you used your facial expression to make the O too.  Very good.', '2013-02-26 10:03:55.000000', NULL, 1),
(6986478, 1053640, 82999, '<td valign="top">Not sure how this fits the challenge?  And there''s too much noise in the image.<br/> <br/>I, however, think the base idea is very good.  <br/> <br/>Seems like you could have taken multiple images of random folks and hung them from the line with a spot on your portrait and that would have been a home run.<br/> <br/>As is I can only make out three images and those are very feint.</td>', 'Not sure how this fits the challenge?  And there''s too much noise in the image. I, however, think the base idea is very good.   Seems like you could have taken multiple images of random folks and hung them from the line with a spot on your portrait and that would have been a home run. As is I can only make out three images and those are very feint.', '2013-02-26 10:06:18.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6986483, 1054113, 82999, '<td valign="top">I quite like this scene.  Currently, my pic to win.  Your self portrait does stand out from the business clad folks.  And I find it intriguing that you''re sitting on the floor reading a book and no one is paying attention to you.  I just can''t make up my mind if the ghostly image of the man touching the women on the phone helps or hurt.  The image is soo strong it pulls me out of the image. I tend to look at that moment more than anything else.</td>', 'I quite like this scene.  Currently, my pic to win.  Your self portrait does stand out from the business clad folks.  And I find it intriguing that you''re sitting on the floor reading a book and no one is paying attention to you.  I just can''t make up my mind if the ghostly image of the man touching the women on the phone helps or hurt.  The image is soo strong it pulls me out of the image. I tend to look at that moment more than anything else.', '2013-02-26 10:12:37.000000', NULL, 1),
(6986485, 1053875, 82999, '<td valign="top">One of the better images.  I really enjoy and think its creative.  Think the post processing could have been stronger.  Punchier.</td>', 'One of the better images.  I really enjoy and think its creative.  Think the post processing could have been stronger.  Punchier.', '2013-02-26 10:14:13.000000', NULL, 1),
(6986486, 1054001, 82999, '<td valign="top">Definitely one of the better images in the bunch.  The processing is very strong.  My only nit is the blurred person walking on the left is a bit overpowering.  Kinda of pulls my eye away.  Wish it was a bit more subdued like the ones on the right.  But, otherwise this is my pics to ribbon.</td>', 'Definitely one of the better images in the bunch.  The processing is very strong.  My only nit is the blurred person walking on the left is a bit overpowering.  Kinda of pulls my eye away.  Wish it was a bit more subdued like the ones on the right.  But, otherwise this is my pics to ribbon.', '2013-02-26 10:15:35.000000', NULL, 1),
